  if(any&&skySave.lat.value.trim()==='') skySave.lat.setCustomValidity(T('saveSkyBothCoords','Add both latitude and longitude'));
  if(any&&skySave.lon.value.trim()==='') skySave.lon.setCustomValidity(T('saveSkyBothCoords','Add both latitude and longitude'));
