function enterRunning(){
  if(!state.started || state.needsReset){ state.started=true; state.needsReset=false; resetSession(); clearTempleResume(); }
  try{ localStorage.setItem('aimdojo.seen','1'); }catch(e){}
  document.body.classList.remove('overlay-paused');
  if(CFG.chorus.on) chorusHush();   // THE STANDING CHORUS never follows you into the field: the held menu stems let go AND the bus goes to gain 0 here, so not even a release tail crosses into play. Raw boolean first
  closeTransitEssayReader(false); state.running=true; overlay.classList.add('hidden'); clock.getDelta(); applyAudioState(); syncTransport();
  if(_themeReveal){ _themeReveal=false; if(!trainMode) flashTheme(); else showGhostToast(T('trainerToast','MOONLINE TRAINING')); }   // ONE SURFACE, ONE LINE at the threshold: full runs take the theme flash, the trainer announces itself. THE SKY DEALS THE NIGHT does not add a second one — flashTheme itself decides whether that flash names the song or names the night (1.1)
  if(trainMode && trainCoachEl && trainCoachEl.textContent) trainCoachEl.classList.add('on');
  try{ if(pocketLive()) pocketUpdateLawHud(); }catch(e){}
  reconcileTargetSounds();
  if(MOBILE) touchUI.classList.add('show');
  // Pause / task-switch: restore Sky Temple with prior selection + focus (study HUD reloads).
  if(_templeResumeWanted) restoreTempleAfterResume();
}
function exitRunning(){
  // Remember temple across pause / tab-hide so RESUME returns to the investigation, not the dojo.
  if(templeActive) exitSkyTemple({forPause:true, resume:false, toast:false, audio:false});
  rhythmGeneration++; _skySelectHeld=false; _skySelectUsed=false;
  bowReset();   // THE BOW and the pause are distinct exits: an ESC (or tab-hide) mid-ceremony abandons it and puts the tempo, the glyph and the spawn gate back. No-op when no Bow is running — including on the Bow's OWN exit, which already reset itself.
  if(CFG.stars.on) starFlyClear();   // pausing lands every voice still in the air: the line has nothing left to fly over, and a return that already happened must not depend on the player coming back
  abortFlickBonus();   // RAIL-FLICK BONUS: pausing forfeits any pending cascade — un-flag locked orbs, unfreeze the field (they resume with full life)
  try{ clearListen(true); }catch(e){}   // drop study card with pause (Esc = pause only; card must not linger under the overlay)
  state.running=false; applyAudioState(); syncTransport();
  if(MOBILE) touchUI.classList.remove('show');
  if(trainCoachEl) trainCoachEl.classList.remove('on');   // coach is in-world only
  try{ pocketUpdateLawHud(); }catch(e){}   // hide LAW while paused
  showPause();
  scheduleReverbBuild(120);
}
